import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"陶壅","description":"","frontmatter":{"title":"陶壅","date":"2026-11-24T00:00:00.000Z","seq":46,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王褒","source_book":"楚辞","prev":{"text":"思忠","link":"/blogs/楚辞/思忠.html"},"next":{"text":"株昭","link":"/blogs/楚辞/株昭.html"}},"headers":[],"relativePath":"blogs/楚辞/陶壅.md","filePath":"blogs/楚辞/陶壅.md"}'),o={name:"blogs/楚辞/陶壅.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="陶壅" tabindex="-1">陶壅 <a class="header-anchor" href="#陶壅" aria-label="Permalink to &quot;陶壅&quot;">​</a></h1><p class="poem-meta">先秦 · 王褒　·　九怀</p><div class="poem"><p class="poem-stanza">览杳杳兮世惟，余惆怅兮何归。</p><p class="poem-stanza">伤时俗兮溷乱，将奋翼兮高飞。</p><p class="poem-stanza">驾八龙兮连蜷，建虹旌兮威夷。</p><p class="poem-stanza">观中宇兮浩浩，纷翼翼兮上跻。</p><p class="poem-stanza">浮溺水兮舒光，淹低佪兮京沶。</p><p class="poem-stanza">屯余车兮索友，睹皇公兮问师。</p><p class="poem-stanza">道莫贵兮归真，羡余术兮可夷。</p><p class="poem-stanza">吾乃逝兮南娭，道幽路兮九疑。</p><p class="poem-stanza">越炎火兮万里，过万首兮嶷嶷。</p><p class="poem-stanza">济江海兮蝉蜕，绝北梁兮永辞。</p><p class="poem-stanza">浮云郁兮昼昏，霾土忽兮塺々。</p><p class="poem-stanza">息阳城兮广夏，衰色罔兮中怠。</p><p class="poem-stanza">意晓阳兮燎寤，乃自诊兮在兹。</p><p class="poem-stanza">思尧舜兮袭兴，幸咎繇兮获谋。</p><p class="poem-stanza">悲九州兮靡君，抚轼叹兮作诗。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
